-- Main database schema (schema version 2).
-- Timestamps are Unix milliseconds stored as integers.
-- Captured from the legacy runtime on 2026-10-09, with datetime columns changed to integer.
-- Changes after the capture are made here by hand; the runtime adds missing tables, columns, and indexes at startup.
CREATE TABLE `users` (`id` integer PRIMARY KEY AUTOINCREMENT,`username` text NOT NULL,`email` text NOT NULL,`password_hash` text NOT NULL,`nickname` text,`avatar` text,`phone` text,`role` text DEFAULT "user",`status` text DEFAULT "active",`daily_quota` integer DEFAULT 100,`used_quota` integer DEFAULT 0,`total_creations` integer DEFAULT 0,`last_login_at` integer,`last_login_ip` text,`created_at` integer,`updated_at` integer,`deleted_at` integer);
CREATE INDEX `idx_users_deleted_at` ON `users`(`deleted_at`);
CREATE INDEX `idx_users_status` ON `users`(`status`);
CREATE INDEX `idx_users_role` ON `users`(`role`);
CREATE UNIQUE INDEX `idx_users_email` ON `users`(`email`);
CREATE UNIQUE INDEX `idx_users_username` ON `users`(`username`);
CREATE TABLE `ai_models` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer NOT NULL,`name` text NOT NULL,`provider` text NOT NULL,`model_name` text NOT NULL,`api_key` text NOT NULL,`base_url` text,`is_default` numeric DEFAULT false,`is_active` numeric DEFAULT true,`is_system_builtin` numeric DEFAULT false,`description` text,`capabilities` JSON,`created_at` integer,`updated_at` integer);
CREATE INDEX `idx_ai_models_provider` ON `ai_models`(`provider`);
CREATE INDEX `idx_ai_models_user_id` ON `ai_models`(`user_id`);
CREATE TABLE `ai_model_usage_logs` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer NOT NULL,`ai_model_id` integer NOT NULL,`creation_id` integer,`provider` text NOT NULL,`model_name` text NOT NULL,`tool` text,`request_type` text NOT NULL,`input_content` text,`output_content` text,`prompt_tokens` integer,`completion_tokens` integer,`total_tokens` integer,`status` text DEFAULT "success",`error_message` text,`response_time_ms` integer,`extra_data` JSON,`created_at` integer);
CREATE INDEX `idx_ai_model_usage_logs_created_at` ON `ai_model_usage_logs`(`created_at`);
CREATE INDEX `idx_ai_model_usage_logs_status` ON `ai_model_usage_logs`(`status`);
CREATE INDEX `idx_ai_model_usage_logs_request_type` ON `ai_model_usage_logs`(`request_type`);
CREATE INDEX `idx_ai_model_usage_logs_tool` ON `ai_model_usage_logs`(`tool`);
CREATE INDEX `idx_ai_model_usage_logs_provider` ON `ai_model_usage_logs`(`provider`);
CREATE INDEX `idx_ai_model_usage_logs_creation_id` ON `ai_model_usage_logs`(`creation_id`);
CREATE INDEX `idx_ai_model_usage_logs_ai_model_id` ON `ai_model_usage_logs`(`ai_model_id`);
CREATE INDEX `idx_ai_model_usage_logs_user_id` ON `ai_model_usage_logs`(`user_id`);
